import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{C as i,S as a,_ as o,a as s,b as c,c as l,d as u,f as d,g as f,h as p,l as m,m as h,o as g,p as _,s as v,u as y,v as b,w as x,x as S,y as C}from"./chunks/assets.BL_qWEMe.js";var w=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}`),T={name:`troubleshooting.md`},E=x+` 1x, `+i+` 2x`,D=a+` 1x, `+S+` 2x`,O=c+` 1x, `+C+` 2x`,k=b+` 1x, `+o+` 2x`,A=f+` 1x, `+p+` 2x`,j=h+` 1x, `+_+` 2x`,M=d+` 1x, `+u+` 2x`,N=y+` 1x, `+m+` 2x`,P=l+` 1x, `+v+` 2x`,F=g+` 1x, `+s+` 2x`;function I(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>The module has a troubleshooting page where you can easily fix common problems.</p><p>To access the troubleshooting page, open the main configuration page of the module, then click the following button.</p><p><img src="/webp/troubleshoot-btn.png-90-1791641243360.webp" srcset="`+E+`" alt="Troubleshoot btn" title="" width="1326" height="732" loading="lazy" style="width:663px;"></p><h2 id="the-module-is-not-displayed" tabindex="-1">The module is not displayed <a class="header-anchor" href="#the-module-is-not-displayed" aria-label="Permalink to “The module is not displayed”">​</a></h2><p>In some cases, the module gets removed by the theme from some essential hooks.</p><p>To restore it, select the available hooks then restore them like this</p><p><img src="/webp/hooks.jpg-90-1791641243303.webp" srcset="`+D+`" alt="Hooks" title="" width="1392" height="714" loading="lazy" style="width:696px;"></p><p>This confirmation should be displayed</p><p><img src="/webp/hooks-restored.jpg-90-1791641243302.webp" srcset="`+O+`" alt="Hooks restored" title="" width="1392" height="816" loading="lazy" style="width:696px;"></p><h2 id="the-customized-summary-is-not-formatted-properly" tabindex="-1">The customized summary is not formatted properly <a class="header-anchor" href="#the-customized-summary-is-not-formatted-properly" aria-label="Permalink to “The customized summary is not formatted properly”">​</a></h2><p>If the summary is not displayed correctly, you can fix the templates in the troubleshooting page.</p><p><img src="/webp/summary-misformat.jpg-90-1791641243342.webp" srcset="`+k+`" alt="Summary misformat" title="" width="910" height="470" loading="lazy" style="width:455px;"></p><p>Scroll down to the template fix section, then click the apply button</p><p><img src="/webp/template-fix.jpg-90-1791641243348.webp" srcset="`+A+`" alt="Template fix" title="" width="1392" height="698" loading="lazy" style="width:696px;"></p><p>The module will display this confirmation if the templates were fixed correctly</p><p><img src="/webp/template-fixed.jpg-90-1791641243348.webp" srcset="`+j+`" alt="Template fixed" title="" width="1392" height="744" loading="lazy" style="width:696px;"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>After applying the template fix, clear the PrestaShop cache for the fix to have effect.</p></div><p>The customization should then be displayed correctly like this</p><p><img src="/webp/customization-summary.jpg-90-1791641243288.webp" srcset="`+M+`" alt="Customization summary" title="" width="1288" height="808" loading="lazy" style="width:644px;"></p><p>If this doesn&#39;t work, it means that either that the module couldn&#39;t fix the files because of a permission problem on your server or that PrestaShop could not clear the cache properly due to insufficient permissions.</p><p>In that case, you need to perform the edits manually by following <a href="https://gist.github.com/unlocomqx/f0b86a1ce938405c315d5de979011b95" target="_blank" rel="noreferrer">this guide</a></p><p>After applying the fix, make sure to also delete or rename the folder <code>/var/cache</code> manually if needed.</p><h2 id="upgrade-checker" tabindex="-1">Upgrade checker <a class="header-anchor" href="#upgrade-checker" aria-label="Permalink to “Upgrade checker”">​</a></h2><p>You can check the module installation using the upgrade checker</p><p>To access it, click this button which you can find in the module configuration page</p><p><img src="/webp/upgrade-checker-btn.png-90-1791641243360.webp" srcset="`+N+`" alt="Upgrade checker btn" title="" width="1144" height="528" loading="lazy" style="width:572px;"></p><p>The versions will be displayed like this</p><p><img src="/webp/versions-list.jpg-90-1791641243361.webp" srcset="`+P+`" alt="Versions list" title="" width="1234" height="874" loading="lazy" style="width:617px;"></p><p>If an upgrade has previously failed, you can retry it like this</p><p><img src="/webp/retry-upgrade.png-90-1791641243333.webp" srcset="`+F+`" alt="Retry upgrade" title="" width="660" height="894" loading="lazy" style="width:330px;"></p>`,31)]])}var L=e(T,[[`render`,I]]);export{w as __pageData,L as default};